def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r, c = next((i, j) for i in range(h) for j in range(w) if grid[i][j] == 3)

    # Spiral outward, beginning by moving up. Preserve the 2 markers.
    directions = [(-1,  0), (0, 1), (1, 0), (0, -1)]
    length = 2
    segment = 0
    while length <= 2 * max(h, w):
        dr, dc = directions[segment % 4]
        for _ in range(length):
            r += dr
            c += dc
            if 0 <= r < h and 0 <= c < w and grid[r][c] != 2:
                out[r][c] = 3
        segment += 1
        if segment % 2 == 0:
            length += 2

    # The spiral's final outward sweep completes the bottom edge when it
    # reaches the lower boundary.
    if r >= h:
        for j in range(w):
            if grid[h - 1][j] != 2:
                out[h - 1][j] = 3
    return out
